#!/usr/bin/env python3
import csv, json
from datetime import datetime, timezone, timedelta
from zoneinfo import ZoneInfo

TZ = ZoneInfo('America/Los_Angeles')
TARGET_DAY = datetime(2026, 11, 27, tzinfo=TZ)
START = TARGET_DAY.astimezone(timezone.utc)
END = datetime(2026, 11, 28, tzinfo=TZ).astimezone(timezone.utc)
CT_CHANGE_LOCAL = datetime(2026, 11, 13, 10, 0, tzinfo=TZ)
ROLLOVER = 1000000.0  # 6 digits and one decimal, after 999999.9 rolls to 0.0

rows = []
with open('readings.csv', newline='') as f:
    for row in csv.DictReader(f):
        dt = datetime.fromisoformat(row['ts'])
        if dt.tzinfo is None:
            # README states ts is UTC.
            dt = dt.replace(tzinfo=timezone.utc)
        else:
            dt = dt.astimezone(timezone.utc)
        rows.append((dt, float(row['register_kwh']), row['meter_id']))
rows.sort()

flags = []
if len({m for _, _, m in rows}) != 1:
    flags.append('multiple_meter_ids')

# Validate hourly coverage.
if any(rows[i+1][0] - rows[i][0] != timedelta(hours=1) for i in range(len(rows)-1)):
    flags.append('non_hourly_gap_or_duplicate')

# Detect rollover / negative displayed difference.
for (a_dt, a_val, _), (b_dt, b_val, _) in zip(rows, rows[1:]):
    if b_val < a_val:
        flags.append('register_rollover_detected')
        break

by_dt = {dt: val for dt, val, _ in rows}
if START not in by_dt or END not in by_dt:
    result = {
        'status': 'cannot_determine',
        'reason': 'missing exact boundary readings for target local day',
        'flags': flags,
    }
else:
    displayed = by_dt[END] - by_dt[START]
    if displayed < 0:
        displayed += ROLLOVER
        if 'register_rollover_detected' not in flags:
            flags.append('register_rollover_detected')
    # The target day is wholly after the CT change, so true energy is 10x displayed change.
    if START.astimezone(TZ) >= CT_CHANGE_LOCAL:
        answer = round(displayed * 10, 6)
        flags.append('ct_ratio_x10_applied')
    else:
        # Not needed for this target day, but keep script explicit.
        result = {
            'status': 'cannot_determine',
            'reason': 'target interval crosses CT ratio change; split-interval logic not implemented',
            'flags': flags,
        }
        with open('answer.json', 'w') as out:
            json.dump(result, out, separators=(',', ':'))
        raise SystemExit
    # Short unique flags preserving order.
    uniq_flags = []
    for f in flags:
        if f not in uniq_flags:
            uniq_flags.append(f)
    result = {'answer': answer, 'flags': uniq_flags}

with open('answer.json', 'w') as out:
    json.dump(result, out, separators=(',', ':'))
    out.write('\n')
print(json.dumps(result, indent=2))
PY
